// #1191 acceptance — A JOB THAT STARTED CUTTING FINISHES ON ITS OWN PROGRAMS, ACROSS BUILDS.
//
// Generate on build A, program 1 finished on the blank, reload as build B: the Cut step's run card
// reads 'Start program 2 of 2' on A's bytes (#1123 item 8 — the card carries the step's ONE Start;
// the old release step is not rendered with a package), states the one-line origin ('These programs
// were generated by build … on …'), and THIS build's verifier has run over the stored bytes before
// any Load. The
// stored record's build is rewritten to an id that cannot be this build (the spec's stand-in for
// the two-build publish), while the record schema stays readable — the schema, never the build id,
// is the restore gate.
import fs from 'node:fs';
import path from 'node:path';
import type { Page } from '@playwright/test';
import { lanServerPort } from '../../scripts/e2ePort';
import { test, expect } from './fixtures/caseMaker';
import { locationDocument, serveHouse } from './fixtures/fakeHouse';
import { rememberMachine } from './fixtures/rememberMachine';
import { installFakeConsole } from './fixtures/fakeConsole';

test.use({ baseURL: `http://127.0.0.1:${lanServerPort()}` });
test.setTimeout(240_000);

const OLD_BUILD = 'build-A-1191';
const NC1 = 'G90 G21\nG0 Z1\nM3 S10000\nG0 X5 Y5\nG1 Z-1 F100\nG1 X15 Y5 F300\nG1 X15 Y15\nG1 X5 Y15\nG1 X5 Y5\nG0 Z1\nM5\nM02\n';
const NC2 = 'G90 G21\nG0 Z1\nM3 S10000\nG0 X25 Y5\nG1 Z-1 F100\nG1 X35 Y5 F300\nG1 X35 Y15\nG1 X25 Y15\nG1 X25 Y5\nG0 Z1\nM5\nM02\n';

const DOC = JSON.parse(
  fs.readFileSync(path.join(process.cwd(), 'tests', 'unit', 'fixtures', 'location-doc.json'), 'utf8'),
) as { defaults?: Record<string, unknown>; machines: unknown[]; accessories: unknown[]; kind: string; schemaVersion: number; id: string; name: string; createdAt: string };

/** The bench location with the durable half of "program 1 is finished on this blank". */
function locationWithProgramOne(hash: string): unknown {
  const doc = locationDocument() as {
    kind: string;
    schemaVersion: number;
    id: string;
    name: string;
    createdAt: string;
    machines: Array<{ finishedPrograms?: string[] }>;
    accessories: unknown[];
  };
  doc.machines[0]!.finishedPrograms = [hash];
  return {
    kind: doc.kind,
    schemaVersion: doc.schemaVersion,
    id: doc.id,
    name: doc.name,
    createdAt: doc.createdAt,
    machines: doc.machines,
    accessories: doc.accessories,
  };
}

/** Seed the two-program job, its package, and a stored run made by OLD_BUILD. */
async function seedOldBuildRun(page: Page): Promise<void> {
  await page.evaluate(async () => {
    const defaults = (await import('/src/engine/cnc/engrave/defaults.ts' as string)) as {
      defaultEngraveJob: () => Record<string, unknown>;
    };
    const pkgMod = (await import('/src/engine/cnc/engrave/package.ts' as string)) as {
      freezePackage: (job: unknown, inputs: unknown[], at: string) => { ok: boolean; reason?: string; package?: Record<string, unknown> };
      jobFingerprint: (job: unknown) => string;
    };
    const jobStore = (await import('/src/store/engraveJobStore.ts' as string)) as {
      useEngraveJobStore: { getState: () => { replace: (job: unknown) => void } };
    };
    const runStore = (await import('/src/store/engraveRunStore.ts' as string)) as {
      useEngraveRunStore: { setState: (v: unknown) => void };
    };
    const persist = (await import('/src/store/runPersistence.ts' as string)) as {
      persistRunNow: () => Promise<unknown>;
    };
    const IDENTITY = { top: 'top', bottom: 'bottom', left: 'left', right: 'right', front: 'front', back: 'back' };
    const job = defaults.defaultEngraveJob() as Record<string, unknown> & {
      id: string;
      toolKey: string;
      labels: { id: string }[];
      setups: unknown[];
    };
    job.toolKey = 'flat-1.0';
    const ids = job.labels.map((l) => l.id);
    job.setups = [{ id: 's1', orientation: { ...IDENTITY }, mount: { kind: 'vise' }, itemIds: ids, tools: ['flat-1.0'] }];
    const inputs = [
      { setupIndex: 1, setupId: 's1', toolKey: 'flat-1.0', nc: 'G90 G21\nG0 Z1\nM3 S10000\nG0 X5 Y5\nG1 Z-1 F100\nG1 X15 Y5 F300\nG1 X15 Y15\nG1 X5 Y15\nG1 X5 Y5\nG0 Z1\nM5\nM02\n', frameNc: null, programHash: 'h1' },
      { setupIndex: 1, setupId: 's1', toolKey: 'flat-1.0', nc: 'G90 G21\nG0 Z1\nM3 S10000\nG0 X25 Y5\nG1 Z-1 F100\nG1 X35 Y5 F300\nG1 X35 Y15\nG1 X25 Y15\nG1 X25 Y5\nG0 Z1\nM5\nM02\n', frameNc: null, programHash: 'h2' },
    ];
    const made = pkgMod.freezePackage(job, inputs, '2026-11-10T09:00:00.000Z');
    if (!made.ok || made.package === undefined) throw new Error(made.reason ?? 'the package did not freeze');
    const withPkg = { ...job, package: made.package };
    // The store action persists the document (localStorage) so the reload reopens THIS job; the
    // workspace record is what makes the reload land on the CNC Cut half rather than the door.
    jobStore.useEngraveJobStore.getState().replace(withPkg);
    const viewport = (await import('/src/store/viewportStore.ts' as string)) as {
      useViewportStore: { getState: () => { setActiveSidebarSection: (s: string) => void } };
    };
    const project = (await import('/src/store/projectStore.ts' as string)) as {
      useProjectStore: { setState: (v: unknown) => void };
    };
    const cnc = (await import('/src/store/cncModeStore.ts' as string)) as {
      useCncModeStore: { setState: (v: unknown) => void };
    };
    const session = (await import('/src/store/workspaceSession.ts' as string)) as {
      writeWorkspaceSession: () => void;
    };
    viewport.useViewportStore.getState().setActiveSidebarSection('cnc-engrave');
    project.useProjectStore.setState({ welcomeMode: false });
    cnc.useCncModeStore.setState({ mode: 'cut', jobId: (withPkg as { id: string }).id });
    session.writeWorkspaceSession();
    const jobSha = pkgMod.jobFingerprint(withPkg);
    void jobSha; // the record's id is the run's own inputs.job stamp, set below
    const pkgPrograms = (made.package as { programs: { hash: string; nc: string; setupIndex: number; setupId: string; toolKey: string }[] }).programs;
    const verify = {
      ok: true,
      findings: [],
      stats: { lines: 3, cuttingMoves: 0, deepestZ: 0, bbox: { min: [0, 0, -0], max: [1, 1, 0] } },
    };
    const programs = pkgPrograms.map((p, i) => ({
      setupIndex: p.setupIndex,
      setupId: p.setupId,
      toolKey: p.toolKey,
      nc: inputs[i]!.nc,
      verify,
      frameNc: null,
      frameVerify: null,
      programHash: p.hash,
      cam: null,
    }));
    const generated = {
      ok: true,
      stage: 'done',
      findings: [],
      feeds: null,
      threads: null,
      threadMachining: null,
      cam: null,
      nc: programs[0]!.nc,
      verify,
      frameNc: null,
      frameVerify: null,
      facingNc: null,
      facingVerify: null,
      facingToolKey: null,
      facingError: null,
      facingCam: null,
      predicted: [],
      programs,
      errors: [],
    };
    // The stamps the CURRENT stores produce, so the reload's input recheck compares like with like
    // (a fabricated stub would read as "the inputs moved" and stale the run).
    const stamps = (await import('/src/store/engraveRunStore.ts' as string)) as {
      currentRunInputStamps: () => unknown;
      runShopSignature: () => string;
    };
    runStore.useEngraveRunStore.setState({
      generated,
      inputs: stamps.currentRunInputStamps(),
      shopSignature: stamps.runShopSignature(),
      phase: 'ready',
      acknowledged: true,
      oracle: { ok: true, band: 0.016, levels: [], worst: { underCut: 0, overCut: 0 } },
      simStatus: 'ready',
      simDiagnostics: [],
    });
    const record = await persist.persistRunNow();
    if (record === null) throw new Error('the run was not stored');
  });

}

test('#1191 — a job that started on build A continues on program 2 under build B, on A’s bytes', async ({ cm, page }) => {
  await serveHouse(page, {
    location: locationWithProgramOne('h1'),
    defaults: DOC.defaults,
    writes: 'reject',
  });
  await installFakeConsole(page);
  await cm.ready();
  await rememberMachine(page, '<Idle|MPos:0,0,0|WPos:0,0,0|S:0.0,10000.0,100.0,0,25.8,24.0,0,0,0,0>');

  // The location's machine frame must be READ before the run's input stamps are taken: a null
  // calibration at seed time would read as "the machine frame changed" on the reloaded build.
  await page.waitForFunction(
    async () => {
      const s = (await import('/src/store/settingsStore.ts' as string)) as {
        useSettingsStore: { getState: () => { machineCalibration: unknown } };
      };
      return s.useSettingsStore.getState().machineCalibration !== null;
    },
    undefined,
    { timeout: 30_000 },
  );

  // THE RECORD'S BUILD IS FORCED AT THE IO SEAM (D's diagnosis). Seeding the run store changes
  // fields the persistence subscription watches, so a 150 ms debounced save is pending when the
  // seed ends; without this wrapper it would put runBuildId() back and the reloaded page would see
  // a same-build record, never the cross-build case. Every save in build A's page writes A's id.
  await page.evaluate(async (oldBuild) => {
    const m = (await import('/src/store/runPersistence.ts' as string)) as {
      setRunRecordIO: (io: unknown) => void;
    };
    const open = (): Promise<IDBDatabase> =>
      new Promise((resolve, reject) => {
        const request = indexedDB.open('casemaker-runs', 1);
        request.onupgradeneeded = () => {
          const db = request.result;
          if (!db.objectStoreNames.contains('runs')) {
            const store = db.createObjectStore('runs', { keyPath: 'id' });
            store.createIndex('jobSha', 'jobSha');
          }
        };
        request.onsuccess = () => resolve(request.result);
        request.onerror = () => reject(request.error);
      });
    m.setRunRecordIO({
      put: async (record: Record<string, unknown> & { id: string }) => {
        const db = await open();
        await new Promise<void>((resolve, reject) => {
          const tx = db.transaction('runs', 'readwrite');
          tx.objectStore('runs').put({ ...record, build: oldBuild, savedAt: '2026-11-10T09:00:00.000Z' });
          tx.oncomplete = () => resolve();
          tx.onerror = () => reject(tx.error);
        });
        db.close();
      },
      listByJob: async (jobSha: string) => {
        const db = await open();
        const all = await new Promise<{ jobSha?: string }[]>((resolve, reject) => {
          const get = db.transaction('runs', 'readonly').objectStore('runs').getAll();
          get.onsuccess = () => resolve(get.result as { jobSha?: string }[]);
          get.onerror = () => reject(get.error);
        });
        db.close();
        return all.filter((record) => record.jobSha === jobSha);
      },
    });
  }, OLD_BUILD);

  // BUILD A: the job, its two programs, and the settled run stored with A's identity.
  await seedOldBuildRun(page);

  // The record is still A's when the page goes: a save that raced the reload would mask the case.
  const storedBuild = await page.evaluate(async () => {
    const db = await new Promise<IDBDatabase>((resolve, reject) => {
      const request = indexedDB.open('casemaker-runs', 1);
      request.onsuccess = () => resolve(request.result);
      request.onerror = () => reject(request.error);
    });
    const record = await new Promise<{ build: string }>((resolve, reject) => {
      const get = db.transaction('runs', 'readonly').objectStore('runs').getAll();
      get.onsuccess = () => resolve(get.result[0] as { build: string });
      get.onerror = () => reject(get.error);
    });
    db.close();
    return record.build;
  });
  expect(storedBuild).toBe(OLD_BUILD);

  // BUILD B: a fresh page (a new build in the acceptance's terms) restores the job and the run.
  // ONE navigation only: `cm.ready()` navigates itself, and a second load could re-save the record
  // under this build before the assertions read the cross-build state.
  await page.goto('/');
  await page.waitForFunction(() => Boolean(window.__caseMaker?.apiVersion === 1), undefined, { timeout: 30_000 });
  await page.evaluate(async () => {
    await window.__caseMaker!.waitForIdle();
  });
  // THE BOOT RESTORE IS ASYNCHRONOUS: it waits briefly for the house reads before reading the
  // record. Wait for it to settle rather than sampling mid-flight.
  await page.waitForFunction(
    async () => {
      const r = (await import('/src/store/engraveRunStore.ts' as string)) as {
        useEngraveRunStore: { getState: () => { generated: unknown; restoreNote: string | null } };
      };
      const s = r.useEngraveRunStore.getState();
      return s.generated !== null || s.restoreNote !== null;
    },
    undefined,
    { timeout: 20_000 },
  );
  // The machine observation is not persisted: the reloaded build learns it again (as a probe would).
  await rememberMachine(page, '<Idle|MPos:0,0,0|WPos:0,0,0|S:0.0,10000.0,100.0,0,25.8,24.0,0,0,0,0>');
  // The workspace record restores the CNC Cut half; the sidebar button toggles, so press it only
  // if this build landed on the door instead.
  if (!(await page.getByTestId('engrave-panel').isVisible().catch(() => false))) {
    await page.getByTestId('sidebar-button-cnc-engrave').click();
  }
  await expect(page.getByTestId('engrave-panel')).toBeVisible();
  await page.getByTestId('cnc-mode-cut').click();
  await expect(page.getByTestId('engrave-cut-surface')).toBeVisible();

  // THE ONE LINE: where these programs came from, on the Cut step the operator is on.
  await expect(page.getByTestId('engrave-cut-restore-note')).toContainText(`generated by build ${OLD_BUILD}`);

  // THIS BUILD'S RE-CHECK runs over the stored bytes; the step states when it has finished.
  await expect(page.getByTestId('engrave-run-restore-checking')).toHaveCount(0, { timeout: 120_000 });

  // Program 1 is finished on the blank (the durable machine record), so the release continues at
  // program 2 — never a fresh plan or a restart at program 1.
  const step1 = page.getByTestId('engrave-cut-step-1');
  if (!(await step1.evaluate((el) => (el as HTMLDetailsElement).open))) {
    await page.getByTestId('engrave-cut-step-1-summary').click();
  }
  // The restored step 2 is current and its restart line overlays the fold's edge; the statement is
  // one checkbox, so it is ticked directly where the operator's press lands.
  await page.evaluate(() => document.querySelector<HTMLInputElement>('[data-testid="engrave-ack"]')?.click());
  await expect(page.getByTestId('engrave-ack')).toBeChecked();
  const step3 = page.getByTestId('engrave-cut-step-3');
  if (!(await step3.evaluate((el) => (el as HTMLDetailsElement).open))) {
    await page.getByTestId('engrave-cut-step-3-summary').click();
  }

  // #1127 — the cutter rows are settled through the job's own action (the fake serves no upload).
  await expect(page.getByTestId('engrave-cutter-row').first()).toBeVisible({ timeout: 60_000 });
  await page.evaluate(async () => {
    const j = (await import('/src/store/engraveJobStore.ts' as string)) as {
      useEngraveJobStore: {
        getState: () => {
          job: { package?: { hash: string; programs: { toolKey: string }[] } };
          setCutterChecklistEntry: (hash: string, key: string, entry: { state: 'located'; at: string }) => void;
        };
      };
    };
    const job = j.useEngraveJobStore.getState().job;
    const pkg = job.package;
    if (pkg === undefined) return;
    for (const key of [...new Set(pkg.programs.map((p) => p.toolKey))]) {
      j.useEngraveJobStore.getState().setCutterChecklistEntry(pkg.hash, key, { state: 'located', at: new Date().toISOString() });
    }
  });
  // #1123 item 8 — with a package the Cut step's control surface is the run CARD; the old release
  // step is not mounted. Its ONE Start is where the restored release continues.
  await expect(page.getByTestId('engrave-cut-card')).toBeVisible({ timeout: 60_000 });
  // The files are marked on the card (the fake console serves no upload protocol); the press under
  // test is the release's own start, not the upload.
  await page.evaluate(async () => {
    const m = (await import('/src/store/engraveReleaseStore.ts' as string)) as {
      useEngraveReleaseStore: {
        getState: () => { records: Record<string, { phase: string; files: { upload: string }[]; walks: { airwalk: unknown; clean: unknown } }> };
        setState: (v: unknown) => void;
      };
    };
    const state = m.useEngraveReleaseStore.getState();
    const key = '192.0.2.10:2222';
    const rec = state.records[key];
    if (rec === undefined) return;
    m.useEngraveReleaseStore.setState({
      records: {
        ...state.records,
        [key]: {
          ...rec,
          phase: rec.phase === 'idle' ? 'ready' : rec.phase,
          files: rec.files.map((f) => ({ ...f, upload: 'uploaded' as const })),
          walks: { airwalk: null, clean: null },
        },
      },
    });
  });
  // #1123 — THE CARD IS GATED ON THE RESTORED RUN'S OWN RE-CHECK: until this build's verifier and
  // simulate-only sweep have read the stored bytes, its start reason reads "checking the restored
  // run against this shop…" and no release record is planned. Wait for THAT gate to clear (the
  // Design panel's indicator may not even be mounted), then the card's plan can name program 2.
  await expect(page.getByTestId('engrave-cut-card-start-reason')).toHaveCount(0, { timeout: 120_000 });
  await expect(page.getByTestId('engrave-cut-card-start')).toHaveText('Start program 2 of 2', { timeout: 30_000 });

  // THE BYTES ARE BUILD A'S, and this build's verifier has re-read them.
  const restored = await page.evaluate(async () => {
    const r = (await import('/src/store/engraveRunStore.ts' as string)) as {
      useEngraveRunStore: { getState: () => { generated: { programs: { nc: string }[] } | null; restoreNote: string | null; restoreChecking: boolean } };
    };
    const s = r.useEngraveRunStore.getState();
    return {
      ncs: s.generated?.programs.map((p) => p.nc) ?? [],
      note: s.restoreNote,
      checking: s.restoreChecking,
    };
  });
  expect(restored.ncs).toEqual([NC1, NC2]);
  expect(restored.note).toContain(`generated by build ${OLD_BUILD}`);
  expect(restored.checking, 'this build’s re-check has finished').toBe(false);
});
